import argparse
import json
import os
import secrets
import sys
from datetime import datetime

def main():
    parser = argparse.ArgumentParser(description='Session management tool')
    subparsers = parser.add_subparsers(dest='command', required=True)

    register_parser = subparsers.add_parser('register', help='Register a new user')
    register_parser.add_argument('username', help='Username to register')
    register_parser.add_argument('password', nargs='?', help='Password (read from stdin)')

    login_parser = subparsers.add_parser('login', help='Login with username and password')
    login_parser.add_argument('username', help='Username to login')
    login_parser.add_argument('password', nargs='?', help='Password (read from stdin)')

    check_parser = subparsers.add_parser('check', help='Check session validity')
    check_parser.add_argument('token', help='Token to check')

    args = parser.parse_args()

    if args.command == 'register':
        if not args.password:
            print("usage", file=sys.stderr)
            sys.exit(2)
        password = input().strip()
        users = load_users()
        users[args.username] = {'password': hash_password(password)}
        save_users(users)
        print("registered")

    elif args.command == 'login':
        if not args.password:
            print("usage", file=sys.stderr)
            sys.exit(2)
        password = input().strip()
        users = load_users()
        if args.username not in users or not verify_password(args.username, password):
            print("login failed")
            sys.exit(1)
        token = generate_token()
        session_file = os.path.join('sessions', f"{args.username}.json")
        os.makedirs('sessions', exist_ok=True)
        with open(session_file, 'w') as f:
            json.dump({
                'username': args.username,
                'timestamp': int(datetime.now().timestamp()),
                'token': token
            }, f)
        print(token)

    elif args.command == 'check':
        token = args.token
        sessions_dir = 'sessions'
        os.makedirs(sessions_dir, exist_ok=True)
        for filename in os.listdir(sessions_dir):
            if filename.endswith('.json'):
                with open(os.path.join(sessions_dir, filename), 'r') as f:
                    session = json.load(f)
                    if session['token'] == token:
                        print(session['username'])
                        sys.exit(0)
        print("no session")
        sys.exit(1)

def load_users():
    users_file = 'users.json'
    if os.path.exists(users_file):
        with open(users_file, 'r') as f:
            return json.load(f)
    return {}

def save_users(users):
    users_file = 'users.json'
    with open(users_file, 'w') as f:
        json.dump(users, f)

def hash_password(password):
    return secrets.hash_for_password(password.encode())

def verify_password(username, password):
    users = load_users()
    if username not in users:
        return False
    stored_hash = users[username]['password']
    return secrets.compare_digest(secrets.hash_for_password(password.encode()), stored_hash)

def generate_token():
    return secrets.token_hex(32)

if __name__ == '__main__':
    main()

import sys
import random
import string

def generate_token():
    chars = string.digits + string.ascii_lowercase
    return ''.join(random.choice(chars) for _ in range(16))

def process_login():
    username = sys.argv[2]
    password = sys.stdin.readline().strip()

    with open('data.txt', 'r') as f:
        lines = f.readlines()

    user_found = False
    user_record = None
    session_record = None

    for line in lines:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == 'user':
            if parts[1] == username:
                user_found = True
                user_record = parts[2]
                break
        elif parts[0] == 'session':
            if parts[1] == username:
                session_record = parts[2]

    if not user_found:
        with open('data.txt', 'a') as f:
            f.write(f'user {username} {password}\n')
        print('registered')
        sys.exit(0)
    elif user_record == password:
        token = generate_token()
        with open('data.txt', 'a') as f:
            f.write(f'session {token} {username}\n')
        print(token)
        sys.exit(0)
    else:
        print('login failed')
        sys.exit(1)

def process_check():
    token = sys.argv[2]

    with open('data.txt', 'r') as f:
        lines = f.readlines()

    username = None
    for line in lines:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == 'session' and parts[1] == token:
            username = parts[2]
            break

    if username:
        print(username)
        sys.exit(0)
    else:
        print('no session')
        sys.exit(1)

if __name__ == '__main__':
    if len(sys.argv) < 3:
        print('Usage: python session_tool.py login <username> or python session_tool.py check <token>')
        sys.exit(1)

    if sys.argv[1] == 'login':
        process_login()
    elif sys.argv[1] == 'check':
        process_check()
    else:
        print('Invalid command')
        sys.exit(1)

