import sys
import os
import json
import random
import string

DATA_FILE = 'data.txt'

# Load data from data.txt or initialize if it doesn't exist
if os.path.exists(DATA_FILE):
    with open(DATA_FILE, 'r') as f:
        data = json.load(f)
else:
    data = {'users': {}, 'sessions': {}}

def save_data():
    with open(DATA_FILE, 'w') as f:
        json.dump(data, f)

def generate_token():
    return ''.join(random.choices(string.ascii_lowercase + string.digits, k=8))

def login(username):
    password = sys.stdin.readline().rstrip('\n')
    if username not in data['users']:
        data['users'][username] = password
        save_data()
        print('registered')
        return
    elif data['users'][username] == password:
        token = generate_token()
        data['sessions'][token] = username
        save_data()
        print(token)
        return
    else:
        print('login failed')
        return

def check(token):
    if token in data['sessions']:
        print(data['sessions'][token])
    else:
        print('no session')

if __name__ == '__main__':
    if len(sys.argv) < 3:
        print('Usage: python session_tool.py <command> <username/token>')
        sys.exit(1)
    command = sys.argv[1]
    identifier = sys.argv[2]
    if command == 'login':
        login(identifier)
    elif command == 'check':
        check(identifier)
    else:
        print('Unknown command')
        sys.exit(1)
